// DictionaryItem is defined locally because the current dictionary types module
// does not export it.
export interface DictionaryItem {
  kelime: string;
  tanim: string;
  kaynak_sozluk: string;
  author?: string;
  publisher?: string;
  year?: string;
  file: string;
  dialect: "BATI" | "DOGU";
}

export interface DictionaryMeta {
  file: string;
  title: string;
  author?: string;
  publisher?: string;
  year?: string;
  dialect: "BATI" | "DOGU";
  total_words?: number;
}

// ==========================================
// 1. FONKSİYONEL SERVİSLER
// ==========================================

export function normalizeDictionaryData(raw: any, meta?: DictionaryMeta): DictionaryItem[] {
  if (!raw) return [];

  // 🎯 SIFIR HATA GÜVENLİK DUVARI: meta her ne koşulda olursa olsun undefined gelse dahi çökmez
  const safeMeta = {
    file: meta?.file || "veri.json",
    title: meta?.title || "İsimsiz Sözlük",
    author: meta?.author || "",
    publisher: meta?.publisher || "",
    year: meta?.year || "",
    dialect: meta?.dialect || "BATI",
  };

  let list: any[] = [];

  // A) Veri Kaynağını Otomatik Tespit Et
  if (Array.isArray(raw)) {
    list = raw;
  } else if (typeof raw === "object" && raw !== null) {
    const source = raw.words && typeof raw.words === "object" ? raw.words : raw;

    if (Array.isArray(source)) {
      list = source;
    } else {
      list = Object.entries(source).map(([key, val]) => {
        if (typeof val === "string") {
          return { kelime: key, tanim: val };
        }
        if (typeof val === "object" && val !== null) {
          return {
            kelime: (val as any).spelling || (val as any).kelime || (val as any).word || key,
            tanim: (val as any).full_definition_in_html || (val as any).tanim || (val as any).definition || (val as any).meaning || "",
          };
        }
        return null;
      }).filter(Boolean);
    }
  }

  // B) Elemanları Standardize Et, HTML Temizle ve Künye Ekle
  return list
    .map((item: any): DictionaryItem | null => {
      if (!item) return null;

      const rawKelime = item.kelime || item.spelling || item.word || "";
      let rawTanim = item.tanim || item.full_definition_in_html || item.definition || item.meaning || "";

      if (typeof rawTanim === "string" && rawTanim.includes("<")) {
        rawTanim = rawTanim.replace(/<[^>]*>?/gm, "").trim();
      }

      const kelime = String(rawKelime).trim();
      const tanim = String(rawTanim).trim();

      if (!kelime || !tanim) return null;

      return {
        kelime,
        tanim,
        kaynak_sozluk: safeMeta.title,
        author: safeMeta.author,
        publisher: safeMeta.publisher,
        year: safeMeta.year,
        file: safeMeta.file,
        dialect: safeMeta.dialect as "BATI" | "DOGU",
      };
    })
    .filter((item): item is DictionaryItem => item !== null);
}

// JSON Dosyası Yükleme
export async function loadDictionary(fileName: string, meta?: DictionaryMeta): Promise<DictionaryItem[]> {
  const res = await fetch(`/data/${fileName}`);
  if (!res.ok) throw new Error(`${fileName} verisi okunamadı.`);
  const raw = await res.json();
  return normalizeDictionaryData(raw, meta);
}

// Arama Fonksiyonu
export function searchInJSON(data: DictionaryItem[], query: string, limit = 50): DictionaryItem[] {
  if (!Array.isArray(data)) return [];

  const clean = query.trim().toLowerCase();
  if (!clean) return [];

  return data
    .filter(
      (item) =>
        item.kelime?.toLowerCase().includes(clean) ||
        item.tanim?.toLowerCase().includes(clean)
    )
    .slice(0, limit);
}

// Günün Kelimesi
export function getDailyWordFromJSON(data: DictionaryItem[]): DictionaryItem | null {
  if (!Array.isArray(data) || data.length === 0) return null;

  const today = new Date().toISOString().slice(0, 10);
  let hash = 0;
  for (let i = 0; i < today.length; i++) hash += today.charCodeAt(i);
  return data[Math.abs(hash) % data.length];
}

// ==========================================
// 2. CLASS TABANLI SERVİS (Bellek Önbellekli)
// ==========================================

class DictionaryService {
  private cache: Map<string, DictionaryItem[]> = new Map();

  async loadDictionary(fileName: string, meta?: DictionaryMeta): Promise<DictionaryItem[]> {
    if (this.cache.has(fileName)) {
      return this.cache.get(fileName)!;
    }
    const data = await loadDictionary(fileName, meta);
    this.cache.set(fileName, data);
    return data;
  }

  async search(query: string, fileName: string, meta?: DictionaryMeta, limit = 50): Promise<DictionaryItem[]> {
    const data = await this.loadDictionary(fileName, meta);
    return searchInJSON(data, query, limit);
  }

  async getDailyWord(fileName: string, meta?: DictionaryMeta): Promise<DictionaryItem | null> {
    const data = await this.loadDictionary(fileName, meta);
    return getDailyWordFromJSON(data);
  }
}

export const dictionaryService = new DictionaryService();