"use client";

import React, { useState, useEffect, useRef, useMemo, useCallback } from "react";
import { dictionaryService } from "@/lib/DictionaryService";
import { DictionaryItem } from "@/types/dictionary";
import AkilliKlavye from "../src/compenents/AkilliKlavye";
import { 
  loadDictionary, 
  searchInJSON, 
  getDailyWordFromJSON, 
  DictionaryItem 
} from "../src/lib/DictionaryService";
// ==========================================
// TİP VE SABİT TANIMLAMALARI
// ==========================================
export type AramaModu = "baslayan" | "icinde" | "tam";

export interface GruplanmisKelime {
  kelime: string;
  kaynaklar: DictionaryItem[];
}

const LIMIT = 20;

const KURUMSAL = {
  kirmizi: "#FF4030",
  kirmiziKoyu: "#E02E1F",
  kirmiziAcik: "#FFF1F0",
  sari: "#FFC604",
  sariKoyu: "#D9A400",
  sariAcik: "#FFFBEB",
};

const BATI_SOZLUKLERI: Record<string, string> = {
  "0.Ady-Ady_AIG.json": "Adıgece Açıklamalı Sözlük — Адыгабзэм изэхэф гущı1алъ (2006)",
  "1.Ady-Ady_AP.json": "Adıgece-Rusça Sözlük — Prof. Dr. Mirabil L. Apaşev (2008)",
  "2.Ady-Ara.json": "Adıgece-Arapça Sözlük — Dr. Adel Abdulsalam Lash (2013)",
  "3.Ady-En.json": "Adıgece-İngilizce Sözlük — Адыгэбзэ-инджылыбзэ гущı1алъэ",
  "4.Ady-En_Adam.json": "Adam Shagash Adıgece-İngilizce Sözlük (2020)",
  "10.En-Ady_Adam.json": "Adam Shagash İngilizce-Adıgece Sözlük (2020)",
  "23.Rus-Ady_Blaghoj.json": "Blaghoj Rusça-Adıgece Sözlük — Prof. Dr. Ramazan Blaghoj (1991)",
  "24.Rus-Ady_UAG.json": "Odezhdeko Rusça-Adıgece Sözlük — U. A. Gethanoko (1960)",
  "25.Rus-Ady_UASP.json": "Rusça-Adıgece Okul Sözlüğü (1991)",
  "29.Tur-Ady_Teshu.json": "Teshu Türkçe-Adıgece Sözlük — Cevdet Tharkaho (1991)",
  "30.Ady-Rus_ThreeVolumes.json": "3 Ciltlik Büyük Adıgece-Rusça Sözlük — Maykop Enstitüsü (2011)",
  "31.Tu-Ady_Hilmi.json": "Açumıj Hilmi Türkçe-Adıgece Sözlük (2013)",
  "33.Ady-Rus-1960.json": "Eski Adıgece-Rusça Açıklamalı Sözlük (1960)"
};

const DOGU_SOZLUKLERI: Record<string, string> = {
  "5.Ady-Rus_Qarden.json": "Kardanov Kabardeyce-Rusça Sözlük — B. M. Kardanov (1957)",
  "6.Ady-Rus_Sherdjes.json": "Sherdjes Aliy Kabardeyce/Adıgece-Rusça Sözlük — Ali İ. Çerkes (1994)",
  "11.En-Kbd-Jonty.json": "Jonty Yamisha İngilizce-Kabardeyce Sözlük",
  "12.En-Kbd-Ziwar.json": "Ziwar Gish İngilizce-Kabardeyce Sözlük",
  "13.Kbd-Ar-Jonty.json": "Jonty Yamisha Kabardeyce-Arapça Sözlük",
  "14.Kbd-En-2-Jonty.json": "Jonty Yamisha Kabardeyce-İngilizce Sözlük v2",
  "15.Kbd-En-Jonty.json": "Jonty Yamisha Kabardeyce-İngilizce Sözlük v1",
  "16.Kbd-En-Ziwar.json": "Ziwar Gish Kabardeyce-İngilizce Sözlük",
  "17.Kbd-En_Amjad.json": "Amjad Jaimoukha Kabardeyce-İngilizce Sözlük (1997)",
  "18.Kbd-Ru&En.json": "Kabardeyce - Rusça & İngilizce Çok Dilli Sözlük",
  "19.Kbd-Ru-2-Jonty.json": "Jonty Yamisha Kabardeyce-Rusça Sözlük v2",
  "20.Kbd-Ru-Jonty.json": "Jonty Yamisha Kabardeyce-Rusça Sözlük v1",
  "21.Kbd-Tu-Jonty.json": "Jonty Yamisha Kabardeyce-Türkçe Sözlük",
  "22.Ru-Kbd-Jonty.json": "Jonty Yamisha Rusça-Kabardeyce Sözlük",
  "26.Tu-Kbd-Jonty.json": "Jonty Yamisha Türkçe-Kabardeyce Sözlük",
  "27.Tur-Ady_Abaze.json": "İbrahim Alhas Abaze Türkçe-Adıgece Sözlük (2005)",
  "28.Tur-Ady_Huvaj.json": "Fahri Huvaj Türkçe-Çerkesçe Sözlük (2007)",
  "32.Rus-Kbd_Nalchik_2013.json": "Nalçik Baskısı Okullar İçin Rusça-Kabardeyce Sözlük (2013)"
};

const KAYNAK_HARITASI: Record<string, string> = { ...BATI_SOZLUKLERI, ...DOGU_SOZLUKLERI };

interface TemaTipi {
  arkaPlan: string;
  kartArkaPlan: string;
  yaziAna: string;
  yaziAlt: string;
  kenarlik: string;
  inputArkaPlan: string;
}

export default function Home() {
  const [data, setData] = useState<DictionaryItem[]>([]);
  const [sorgu, setSorgu] = useState("");
  const [dailyWord, setDailyWord] = useState<DictionaryItem | null>(null);
  const [loading, setLoading] = useState(true);

  // Arama ve Filtreleme Durumları
  const [mod, setMod] = useState<AramaModu>("baslayan");
  const [lehceFiltresi, setLehceFiltresi] = useState("tumu");
  const [hedefDil, setHedefDil] = useState("tumu");

  // Sayfalama Durumu
  const [goruntulenenAdet, setGoruntulenenAdet] = useState(LIMIT);

  // Görünüm ve Erişilebilirlik
  const [karanlikMod, setKaranlikMod] = useState(false);
  const [metinBoyutu, setMetinBoyutu] = useState(16);
  const [kopyalandiId, setKopyalandiId] = useState<string | null>(null);
  const [duyuruMetni, setDuyuruMetni] = useState("");

  // Seçili Öğeler ve DOM Referansları
  const [seciliKelimeGrubu, setSeciliKelimeGrubu] = useState<GruplanmisKelime | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const drawerRef = useRef<HTMLDivElement>(null);
  const drawerKapatBtnRef = useRef<HTMLButtonElement>(null);
  const sonOdaklanilanElemanRef = useRef<HTMLElement | null>(null);

  const ozelKarakterler = ["Ӏ", "I", "а", "э", "гь", "кь"];

  // 1. JSON Sözlük Verilerini dictionaryService Üzerinden Yükleme
  useEffect(() => {
    const kayitliKaranlik = localStorage.getItem("darkMode");
    if (kayitliKaranlik) {
      setKaranlikMod(JSON.parse(kayitliKaranlik));
    }

    loadDictionary("0.Ady-Ady_AIG.json")
      .then((dictionary) => {
        setData(dictionary);
        setDailyWord(getDailyWordFromJSON(dictionary));
        setLoading(false);
      })
      .catch((err) => {
        console.error("Veri yükleme hatası:", err);
        setLoading(false);
      });
  }, []);

  const toggleKaranlikMod = () => {
    setKaranlikMod((prev) => {
      const yeniDurum = !prev;
      localStorage.setItem("darkMode", JSON.stringify(yeniDurum));
      setDuyuruMetni(yeniDurum ? "Karanlık tema açıldı." : "Aydınlık tema açıldı.");
      return yeniDurum;
    });
  };

  // Detay Paneli (Drawer) Klavye Kontrolleri
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!seciliKelimeGrubu) return;

      if (e.key === "Escape") {
        setSeciliKelimeGrubu(null);
        return;
      }

      if (e.key === "Tab" && drawerRef.current) {
        const odaklanabilir = drawerRef.current.querySelectorAll<HTMLElement>(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        );
        if (odaklanabilir.length === 0) return;

        const ilk = odaklanabilir[0];
        const son = odaklanabilir[odaklanabilir.length - 1];

        if (e.shiftKey && document.activeElement === ilk) {
          e.preventDefault();
          son.focus();
        } else if (!e.shiftKey && document.activeElement === son) {
          e.preventDefault();
          ilk.focus();
        }
      }
    };

    if (seciliKelimeGrubu) {
      sonOdaklanilanElemanRef.current = document.activeElement as HTMLElement;
      window.addEventListener("keydown", handleKeyDown);
      setTimeout(() => drawerKapatBtnRef.current?.focus(), 50);
    } else {
      sonOdaklanilanElemanRef.current?.focus();
    }

    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [seciliKelimeGrubu]);

  const kaynagiDuzenle = (dosyaAdi?: string) => (!dosyaAdi ? "" : KAYNAK_HARITASI[dosyaAdi] || dosyaAdi);

  const lehceBul = useCallback((dosyaAdi?: string) => {
    if (!dosyaAdi) return null;
    if (dosyaAdi in BATI_SOZLUKLERI) return { etiket: "Batı Adıgece", kod: "bati", renk: "#16a34a" };
    if (dosyaAdi in DOGU_SOZLUKLERI) return { etiket: "Doğu Kabardeyce", kod: "dogu", renk: "#2563eb" };
    return null;
  }, []);

  const hedefDilBul = (dosyaAdi?: string) => {
    if (!dosyaAdi) return "diger";
    const isim = dosyaAdi.toLowerCase();
    if (isim.includes("tur") || isim.includes("tu-")) return "tr";
    if (isim.includes("ara") || isim.includes("-ar")) return "ar";
    if (isim.includes("en") || isim.includes("kbd-en")) return "en";
    if (isim.includes("rus") || isim.includes("ru-")) return "ru";
    return "diger";
  };

  const panoyaKopyala = (kelime: string, tanim?: string, id?: string) => {
    const metin = `${kelime}\n${tanim || ""}`;
    if (navigator.clipboard) {
      navigator.clipboard.writeText(metin)
        .then(() => {
          if (id) setKopyalandiId(id);
          setDuyuruMetni(`${kelime} kelimesi panoya kopyalandı.`);
          setTimeout(() => setKopyalandiId(null), 2000);
        })
        .catch(() => setDuyuruMetni("Kopyalama işlemi başarısız oldu."));
    }
  };

  const metniVurgula = (metin: string, aktifTema: TemaTipi) => {
    const parcalar = metin.split(/(-[^\:]+\:|◊)/g);

    return parcalar.map((parca, index) => {
      if (!parca) return null;

      if (parca === "◊") {
        return (
          <strong key={index} style={{ color: KURUMSAL.kirmizi, margin: "0 4px", fontWeight: "bold" }}>
            ◊
          </strong>
        );
      }

      if (parca.startsWith("-") && parca.endsWith(":")) {
        return (
          <strong key={index} style={{ color: aktifTema.yaziAna, fontWeight: "700" }}>
            {parca}{" "}
          </strong>
        );
      }

      return parca;
    });
  };

  const tanimlariBicimlendir = (tanimMetni?: string, aktifTema?: TemaTipi) => {
    if (!tanimMetni || tanimMetni === "Tanım yok") return null;
    const maddeler = tanimMetni.split(/;|\n/).map((item) => item.trim()).filter(Boolean);
    if (maddeler.length === 0) return null;

    return (
      <div style={{ marginTop: "8px", marginBottom: "8px", textAlign: "left" }}>
        <h4 style={{ fontSize: `${metinBoyutu * 0.85}px`, fontWeight: "600", color: aktifTema?.yaziAlt, marginBottom: "6px" }}>
          Tanımlar:
        </h4>
        <ol style={{ paddingLeft: "22px", margin: 0 }}>
          {maddeler.map((madde, idx) => (
            <li
              key={idx}
              style={{
                color: aktifTema?.yaziAna,
                fontSize: `${metinBoyutu * 0.95}px`,
                lineHeight: "1.6",
                marginBottom: "4px"
              }}
            >
              {metniVurgula(madde, aktifTema!)}
            </li>
          ))}
        </ol>
      </div>
    );
  };

  // 2. Bellek İçi Arama ve Gruplama (searchInJSON tabanlı)
  const filtrelenmisVeGruplanmisSonuclar = useMemo(() => {
    if (!sorgu.trim()) return [];

    let sonucHavuzu = searchInJSON(data, sorgu);

    if (mod === "baslayan") {
      sonucHavuzu = sonucHavuzu.filter((item) =>
        item.kelime.toLowerCase().startsWith(sorgu.trim().toLowerCase())
      );
    } else if (mod === "tam") {
      sonucHavuzu = sonucHavuzu.filter((item) =>
        item.kelime.toLowerCase() === sorgu.trim().toLowerCase()
      );
    }

    const filtrelenmis = sonucHavuzu.filter((item) => {
      const kaynak = (item as any).kaynak_sozluk || (item as any).kaynak;
      if (lehceFiltresi !== "tumu" && kaynak) {
        const lehce = lehceBul(kaynak);
        if (lehce?.kod !== lehceFiltresi) return false;
      }
      if (hedefDil !== "tumu" && kaynak) {
        const dil = hedefDilBul(kaynak);
        if (dil !== hedefDil) return false;
      }
      return true;
    });

    const gruplar: Record<string, DictionaryItem[]> = {};
    filtrelenmis.forEach((item) => {
      const kelimeKey = (item.kelime || "").toLowerCase().trim();
      if (!kelimeKey) return;
      if (!gruplar[kelimeKey]) gruplar[kelimeKey] = [];
      gruplar[kelimeKey].push(item);
    });

    return Object.entries(gruplar).map(([_, kaynaklar]) => ({
      kelime: kaynaklar[0].kelime,
      kaynaklar
    }));
  }, [data, sorgu, mod, lehceFiltresi, hedefDil, lehceBul]);

  const handleSearchChange = (val: string) => {
    setSorgu(val);
    setGoruntulenenAdet(LIMIT);
  };

  const harfEkle = (harf: string) => {
    setSorgu((prev) => {
      const yeni = prev + harf;
      setGoruntulenenAdet(LIMIT);
      return yeni;
    });
    setDuyuruMetni(`${harf} harfi eklendi.`);
    if (inputRef.current) inputRef.current.focus();
  };

  const dahaFazlaYukle = () => {
    setGoruntulenenAdet((prev) => prev + LIMIT);
  };

  // Benzer Kelimeler (Seçili kelimeye göre bellek içi arama)
  const benzerKelimeler = useMemo(() => {
    if (!seciliKelimeGrubu || !seciliKelimeGrubu.kelime) return [];
    const kok = seciliKelimeGrubu.kelime.slice(0, 3).toLowerCase();
    if (!kok) return [];

    const eslesenler = data
      .filter((w) => w.kelime.toLowerCase().startsWith(kok) && w.kelime.toLowerCase() !== seciliKelimeGrubu.kelime.toLowerCase())
      .map((w) => w.kelime);

    return Array.from(new Set(eslesenler)).slice(0, 8);
  }, [seciliKelimeGrubu, data]);

  const tema: TemaTipi = {
    arkaPlan: karanlikMod ? "#0c0f17" : "#f8fafc",
    kartArkaPlan: karanlikMod ? "#141a29" : "#ffffff",
    yaziAna: karanlikMod ? "#f8fafc" : "#0f172a",
    yaziAlt: karanlikMod ? "#cbd5e1" : "#334155",
    kenarlik: karanlikMod ? "#334155" : "#cbd5e1",
    inputArkaPlan: karanlikMod ? "#1a2236" : "#ffffff",
  };

  if (loading) {
    return (
      <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "system-ui, -apple-system, sans-serif", color: "#64748b" }}>
        📖 Sözlük yükleniyor...
      </div>
    );
  }

  const gosterilenGruplar = filtrelenmisVeGruplanmisSonuclar.slice(0, goruntulenenAdet);
  const dahaFazlaVar = filtrelenmisVeGruplanmisSonuclar.length > goruntulenenAdet;

  return (
    <div style={{ backgroundColor: tema.arkaPlan, minHeight: "100vh", padding: "24px 16px", transition: "background-color 0.2s" }}>
      
      {/* WCAG Ekran Okuyucu Canlı Duyuru */}
      <div
        aria-live="polite"
        aria-atomic="true"
        style={{ position: "absolute", width: "1px", height: "1px", padding: 0, margin: "-1px", overflow: "hidden", clip: "rect(0,0,0,0)", border: 0 }}
      >
        {duyuruMetni}
      </div>

      <main style={{ maxWidth: "840px", margin: "0 auto", fontFamily: "system-ui, -apple-system, sans-serif" }}>
        
        {/* Üst Başlık & Açık Mektep Kimliği */}
        <header style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "16px", flexWrap: "wrap", gap: "12px", borderBottom: `2px solid ${KURUMSAL.sari}`, paddingBottom: "14px" }}>
          <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
            <img 
              src="/logo.png" 
              alt="Açık Mektep Logosu" 
              style={{ width: "42px", height: "42px", objectFit: "contain", borderRadius: "8px" }}
              onError={(e) => {
                (e.target as HTMLElement).style.display = "none";
              }}
            />
            <div>
              <span style={{ fontSize: `${metinBoyutu * 0.75}px`, fontWeight: "bold", color: KURUMSAL.kirmizi, textTransform: "uppercase", letterSpacing: "0.08em", display: "block" }}>
                Açık Mektep
              </span>
              <h1 style={{ color: tema.yaziAna, margin: 0, fontSize: `${metinBoyutu * 1.5}px` }}>
                📖 Çerkesçe Sözlük
              </h1>
            </div>
          </div>
          
          <div style={{ display: "flex", gap: "8px", alignItems: "center" }} role="toolbar" aria-label="Görünüm kontrolleri">
            <button
              onClick={() => {
                setMetinBoyutu((p) => {
                  const yeni = Math.max(14, p - 2);
                  setDuyuruMetni(`Yazı boyutu küçültüldü: ${yeni} piksel`);
                  return yeni;
                });
              }}
              aria-label="Yazı boyutunu küçült"
              style={{ padding: "8px 12px", borderRadius: "6px", border: `1px solid ${tema.kenarlik}`, backgroundColor: tema.kartArkaPlan, color: tema.yaziAna, cursor: "pointer", fontWeight: "bold" }}
            >
              A-
            </button>
            <button
              onClick={() => {
                setMetinBoyutu((p) => {
                  const yeni = Math.min(24, p + 2);
                  setDuyuruMetni(`Yazı boyutu büyütüldü: ${yeni} piksel`);
                  return yeni;
                });
              }}
              aria-label="Yazı boyutunu büyüt"
              style={{ padding: "8px 12px", borderRadius: "6px", border: `1px solid ${tema.kenarlik}`, backgroundColor: tema.kartArkaPlan, color: tema.yaziAna, cursor: "pointer", fontWeight: "bold" }}
            >
              A+
            </button>
            <button
              onClick={toggleKaranlikMod}
              aria-pressed={karanlikMod}
              aria-label="Karanlık Temayı Aç/Kapat"
              style={{ padding: "8px 14px", borderRadius: "6px", border: `1px solid ${tema.kenarlik}`, backgroundColor: tema.kartArkaPlan, color: tema.yaziAna, cursor: "pointer" }}
            >
              {karanlikMod ? "☀️ Aydınlık" : "🌙 Karanlık"}
            </button>
          </div>
        </header>

        <p style={{ color: tema.yaziAlt, fontSize: `${metinBoyutu * 0.9}px`, marginBottom: "20px" }}>
        
       
// ✅ Doğru
📚 33 sözlük &bull; 📖 {(data?.length ?? 0).toLocaleString("tr-TR")}+ kayıt
        
          
        </p>

        {/* Günün Kelimesi Kartı */}
        {!sorgu.trim() && dailyWord && (
          <div
            onClick={() => setSeciliKelimeGrubu({ kelime: dailyWord.kelime, kaynaklar: [dailyWord] })}
            style={{
              padding: "14px",
              backgroundColor: karanlikMod ? "#1e293b" : "#e0f2fe",
              borderLeft: "5px solid #0284c7",
              borderRadius: "6px",
              marginBottom: "20px",
              boxShadow: "0 2px 6px rgba(0,0,0,0.05)",
              cursor: "pointer",
              textAlign: "left"
            }}
          >
            <small style={{ color: "#0369a1", fontWeight: "bold", letterSpacing: "0.5px" }}>🌟 GÜNÜN KELİMESİ</small>
            <div style={{ fontSize: "20px", fontWeight: "bold", marginTop: "4px", color: tema.yaziAna }}>
              {dailyWord.kelime}
            </div>
            <div style={{ marginTop: "4px", color: tema.yaziAlt, fontSize: "15px" }}>
              {dailyWord.tanim || (dailyWord as any).anlam}
            </div>
            {(dailyWord as any).kaynak_sozluk && (
              <small style={{ color: tema.yaziAlt, display: "block", marginTop: "6px", fontSize: "12px" }}>
                📚 Kaynak: {kaynagiDuzenle((dailyWord as any).kaynak_sozluk)}
              </small>
            )}
          </div>
        )}

        {/* Hedef Dil Filtreleri */}
        <fieldset style={{ border: "none", padding: 0, margin: "0 0 16px 0" }}>
          <legend style={{ fontSize: `${metinBoyutu * 0.85}px`, fontWeight: "600", color: tema.yaziAlt, marginBottom: "8px" }}>
            Hedef Dil Filtresi:
          </legend>
          <div style={{ display: "flex", gap: "8px", flexWrap: "wrap" }}>
            {[
              { kod: "tumu", etiket: "🌐 Tümü" },
              { kod: "tr", etiket: "🇹🇷 Türkçe" },
              { kod: "ar", etiket: "🇸🇦 Arapça" },
              { kod: "en", etiket: "🇬🇧 İngilizce" },
              { kod: "ru", etiket: "🇷🇺 Rusça" },
            ].map((dil) => (
              <button
                key={dil.kod}
                onClick={() => setHedefDil(dil.kod)}
                aria-pressed={hedefDil === dil.kod}
                style={{
                  padding: "8px 14px",
                  fontSize: `${metinBoyutu * 0.85}px`,
                  fontWeight: hedefDil === dil.kod ? "bold" : "normal",
                  borderRadius: "20px",
                  border: `2px solid ${hedefDil === dil.kod ? KURUMSAL.kirmizi : tema.kenarlik}`,
                  backgroundColor: hedefDil === dil.kod ? KURUMSAL.kirmizi : tema.kartArkaPlan,
                  color: hedefDil === dil.kod ? "#ffffff" : tema.yaziAna,
                  cursor: "pointer"
                }}
              >
                {dil.etiket}
              </button>
            ))}
          </div>
        </fieldset>

        {/* Hızlı Harfler Klavyesi */}
        <fieldset style={{ border: "none", padding: 0, margin: "0 0 16px 0" }}>
          <legend style={{ fontSize: `${metinBoyutu * 0.85}px`, fontWeight: "600", color: tema.yaziAlt, marginBottom: "8px" }}>
            Çerkesçe Hızlı Harfler:
          </legend>
          <div style={{ display: "flex", gap: "8px", flexWrap: "wrap" }}>
            {ozelKarakterler.map((harf, index) => (
              <button
                key={index}
                onClick={() => harfEkle(harf)}
                aria-label={`Arama kutusuna ${harf} karakterini ekle`}
                style={{
                  padding: "8px 16px",
                  fontSize: `${metinBoyutu}px`,
                  fontWeight: "bold",
                  borderRadius: "6px",
                  border: `1px solid ${tema.kenarlik}`,
                  backgroundColor: tema.kartArkaPlan,
                  color: tema.yaziAna,
                  cursor: "pointer"
                }}
              >
                {harf}
              </button>
            ))}
          </div>
        </fieldset>

        {/* Akıllı Klavye Bileşeni */}
        <AkilliKlavye
          inputRef={inputRef}
          sorgu={sorgu}
          setSorgu={handleSearchChange}
          metinBoyutu={metinBoyutu}
          karanlikMod={karanlikMod}
        />

        {/* Arama Alanı ve Filtreler */}
        <div style={{ display: "flex", gap: "10px", marginBottom: "16px", flexWrap: "wrap" }}>
          <div style={{ flex: "1 1 240px", position: "relative" }}>
            <label htmlFor="arama-input" style={{ position: "absolute", width: "1px", height: "1px", overflow: "hidden", clip: "rect(0,0,0,0)" }}>
              Kelime Arayın
            </label>
            <input
              id="arama-input"
              ref={inputRef}
              type="search"
              value={sorgu}
              onChange={(e) => handleSearchChange(e.target.value)}
              placeholder="Kelime veya anlam ara..."
              style={{
                width: "100%",
                padding: "12px 40px 12px 16px",
                fontSize: `${metinBoyutu}px`,
                borderRadius: "8px",
                border: `2px solid ${tema.kenarlik}`,
                backgroundColor: tema.inputArkaPlan,
                color: tema.yaziAna,
                outlineColor: KURUMSAL.kirmizi,
                boxSizing: "border-box"
              }}
            />
            {sorgu && (
              <button
                onClick={() => {
                  handleSearchChange("");
                  inputRef.current?.focus();
                }}
                aria-label="Arama metnini temizle"
                style={{
                  position: "absolute",
                  right: "10px",
                  top: "50%",
                  transform: "translateY(-50%)",
                  background: "transparent",
                  border: "none",
                  color: tema.yaziAlt,
                  cursor: "pointer",
                  fontSize: `${metinBoyutu}px`
                }}
              >
                ✕
              </button>
            )}
          </div>

          <label htmlFor="arama-modu-sec" style={{ position: "absolute", width: "1px", height: "1px", overflow: "hidden", clip: "rect(0,0,0,0)" }}>Arama Yöntemi</label>
          <select
            id="arama-modu-sec"
            value={mod}
            onChange={(e) => setMod(e.target.value as AramaModu)}
            style={{
              padding: "12px",
              fontSize: `${metinBoyutu * 0.9}px`,
              borderRadius: "8px",
              border: `2px solid ${tema.kenarlik}`,
              backgroundColor: tema.inputArkaPlan,
              color: tema.yaziAna,
              cursor: "pointer"
            }}
          >
            <option value="baslayan">İle Başlayan</option>
            <option value="icinde">İçinde Geçen</option>
            <option value="tam">Tam Eşleşen</option>
          </select>

          <label htmlFor="lehce-sec" style={{ position: "absolute", width: "1px", height: "1px", overflow: "hidden", clip: "rect(0,0,0,0)" }}>Lehçe Seçimi</label>
          <select
            id="lehce-sec"
            value={lehceFiltresi}
            onChange={(e) => setLehceFiltresi(e.target.value)}
            style={{
              padding: "12px",
              fontSize: `${metinBoyutu * 0.9}px`,
              borderRadius: "8px",
              border: `2px solid ${tema.kenarlik}`,
              backgroundColor: tema.inputArkaPlan,
              color: tema.yaziAna,
              cursor: "pointer"
            }}
          >
            <option value="tumu">🌐 Tüm Lehçeler</option>
            <option value="bati">🟢 Batı Adıgece</option>
            <option value="dogu">🔵 Doğu Kabardeyce</option>
          </select>
        </div>

        {/* Sonuç Sayacı */}
        {sorgu.trim() && (
          <p style={{ color: tema.yaziAlt, fontSize: `${metinBoyutu * 0.9}px`, marginBottom: "16px" }} role="status">
            Toplam <strong>{filtrelenmisVeGruplanmisSonuclar.length}</strong> kelime grubu bulundu.
          </p>
        )}

        {/* Arama Sonuçları Listesi */}
        <section aria-label="Arama Sonuçları">
          <div style={{ display: "flex", flexDirection: "column", gap: "16px" }}>
            {gosterilenGruplar.map((grup, index) => {
              const ilkKaynak = grup.kaynaklar[0];
              const kaynakDosya = (ilkKaynak as any).kaynak_sozluk || (ilkKaynak as any).kaynak;
              const lehceBilgisi = lehceBul(kaynakDosya);
              const benzersizKey = `grup_${grup.kelime}_${index}`;
              const tanimGosterilecek = ilkKaynak.tanim || (ilkKaynak as any).anlam;

              return (
                <article
                  key={benzersizKey}
                  style={{
                    padding: "20px",
                    borderRadius: "8px",
                    backgroundColor: tema.kartArkaPlan,
                    border: `1px solid ${tema.kenarlik}`,
                    position: "relative",
                    textAlign: "left"
                  }}
                >
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: "12px", marginBottom: "10px" }}>
                    <h3 style={{ margin: 0, color: tema.yaziAna, fontWeight: "bold", fontSize: `${metinBoyutu * 1.3}px` }}>
                      {grup.kelime}
                    </h3>

                    <div style={{ display: "flex", alignItems: "center", gap: "8px", flexShrink: 0 }}>
                      {grup.kaynaklar.length > 1 && (
                        <span style={{ fontSize: `${metinBoyutu * 0.75}px`, fontWeight: "bold", color: "#ffffff", backgroundColor: KURUMSAL.kirmizi, padding: "4px 8px", borderRadius: "12px" }}>
                          {grup.kaynaklar.length} Sözlük
                        </span>
                      )}

                      {lehceBilgisi && (
                        <span style={{ fontSize: `${metinBoyutu * 0.75}px`, fontWeight: "bold", color: lehceBilgisi.renk, backgroundColor: `${lehceBilgisi.renk}15`, padding: "4px 8px", borderRadius: "12px", border: `1px solid ${lehceBilgisi.renk}` }}>
                          {lehceBilgisi.etiket}
                        </span>
                      )}

                      <button
                        onClick={() => panoyaKopyala(ilkKaynak.kelime, tanimGosterilecek, benzersizKey)}
                        aria-label={`${ilkKaynak.kelime} kelimesini ve tanımını panoya kopyala`}
                        title="Panoya Kopyala"
                        style={{ border: `1px solid ${tema.kenarlik}`, borderRadius: "6px", backgroundColor: tema.inputArkaPlan, color: tema.yaziAna, cursor: "pointer", fontSize: `${metinBoyutu * 0.85}px`, padding: "6px 10px" }}
                      >
                        {kopyalandiId === benzersizKey ? "✓ Kopyalandı" : "📋 Kopyala"}
                      </button>
                    </div>
                  </div>

                  {tanimlariBicimlendir(tanimGosterilecek, tema)}

                  {kaynakDosya && (
                    <div style={{ fontSize: `${metinBoyutu * 0.8}px`, color: tema.yaziAlt, fontStyle: "italic", marginTop: "12px", borderTop: `1px dashed ${tema.kenarlik}`, paddingTop: "8px" }}>
                      📚 Kaynak: {kaynagiDuzenle(kaynakDosya)}
                    </div>
                  )}

                  <div style={{ marginTop: "14px", textAlign: "right" }}>
                    <button
                      onClick={() => setSeciliKelimeGrubu(grup)}
                      aria-label={`${grup.kelime} kelimesinin tüm sözlük karşılaştırmalarını aç`}
                      style={{
                        padding: "6px 14px",
                        borderRadius: "6px",
                        backgroundColor: "transparent",
                        border: `1px solid ${KURUMSAL.kirmizi}`,
                        color: KURUMSAL.kirmizi,
                        fontWeight: "600",
                        fontSize: `${metinBoyutu * 0.85}px`,
                        cursor: "pointer"
                      }}
                    >
                      Tüm Kaynakları İncele →
                    </button>
                  </div>
                </article>
              );
            })}

            {dahaFazlaVar && (
              <button
                onClick={dahaFazlaYukle}
                aria-label="Sonraki 20 sonucu listeye ekle"
                style={{
                  padding: "14px",
                  marginTop: "10px",
                  borderRadius: "8px",
                  border: "none",
                  backgroundColor: KURUMSAL.kirmizi,
                  color: "#ffffff",
                  fontWeight: "bold",
                  fontSize: `${metinBoyutu}px`,
                  cursor: "pointer"
                }}
              >
                Daha Fazla Sonuç Göster
              </button>
            )}

            {sorgu && filtrelenmisVeGruplanmisSonuclar.length === 0 && (
              <p style={{ textAlign: "center", color: tema.yaziAlt, fontSize: `${metinBoyutu}px` }} role="status">
                Aradığınız ölçüte uygun sonuç bulunamadı.
              </p>
            )}
          </div>
        </section>

        {/* Kelime Detay Paneli (Drawer) */}
        {seciliKelimeGrubu && (
          <div role="dialog" aria-modal="true" aria-labelledby="drawer-title">
            <div
              onClick={() => setSeciliKelimeGrubu(null)}
              aria-hidden="true"
              style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.6)", backdropFilter: "blur(2px)", zIndex: 1000 }}
            />

            <div
              ref={drawerRef}
              style={{
                position: "fixed",
                top: 0,
                right: 0,
                width: "520px",
                maxWidth: "92%",
                height: "100vh",
                backgroundColor: tema.kartArkaPlan,
                color: tema.yaziAna,
                zIndex: 1001,
                boxShadow: "-4px 0 20px rgba(0,0,0,0.2)",
                display: "flex",
                flexDirection: "column",
                overflowY: "auto",
                padding: "24px",
                boxSizing: "border-box"
              }}
            >
              {/* Header */}
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "20px", borderBottom: `1px solid ${tema.kenarlik}`, paddingBottom: "12px" }}>
                <h2 id="drawer-title" style={{ margin: 0, fontSize: `${metinBoyutu * 1.4}px`, color: tema.yaziAna }}>
                  {seciliKelimeGrubu.kelime}
                </h2>
                <button
                  ref={drawerKapatBtnRef}
                  onClick={() => setSeciliKelimeGrubu(null)}
                  aria-label="Detay panelini kapat"
                  style={{
                    background: "transparent",
                    border: "none",
                    fontSize: "20px",
                    cursor: "pointer",
                    color: tema.yaziAlt,
                    padding: "4px 8px"
                  }}
                >
                  ✕
                </button>
              </div>

              {/* Kaynaklar Listesi */}
              <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: "16px" }}>
                {seciliKelimeGrubu.kaynaklar.map((kaynak, idx) => {
                  const kaynakDosya = (kaynak as any).kaynak_sozluk || (kaynak as any).kaynak;
                  return (
                    <div
                      key={idx}
                      style={{
                        padding: "16px",
                        borderRadius: "8px",
                        backgroundColor: tema.inputArkaPlan,
                        border: `1px solid ${tema.kenarlik}`
                      }}
                    >
                      <div style={{ fontSize: `${metinBoyutu * 0.85}px`, fontWeight: "bold", color: KURUMSAL.kirmizi, marginBottom: "6px" }}>
                        📚 {kaynagiDuzenle(kaynakDosya)}
                      </div>
                      {tanimlariBicimlendir(kaynak.tanim || (kaynak as any).anlam, tema)}
                    </div>
                  );
                })}

                {/* Benzer Kelimeler */}
                {benzerKelimeler.length > 0 && (
                  <div style={{ marginTop: "20px", borderTop: `1px solid ${tema.kenarlik}`, paddingTop: "16px" }}>
                    <h4 style={{ margin: "0 0 10px 0", fontSize: `${metinBoyutu * 0.9}px`, color: tema.yaziAlt }}>
                      🔗 Benzer Kelimeler:
                    </h4>
                    <div style={{ display: "flex", flexWrap: "wrap", gap: "8px" }}>
                      {benzerKelimeler.map((benzer, bIdx) => (
                        <button
                          key={bIdx}
                          onClick={() => {
                            handleSearchChange(benzer);
                            setSeciliKelimeGrubu(null);
                          }}
                          style={{
                            padding: "6px 12px",
                            borderRadius: "16px",
                            border: `1px solid ${tema.kenarlik}`,
                            backgroundColor: tema.kartArkaPlan,
                            color: tema.yaziAna,
                            fontSize: `${metinBoyutu * 0.8}px`,
                            cursor: "pointer"
                          }}
                        >
                          {benzer}
                        </button>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}